export interface LoyverseConfig {
  accessToken: string;
  baseUrl?: string;
}

export interface LoyverseReceiptQuery {
  receiptNumbers?: string[];
  sinceReceiptNumber?: string;
  beforeReceiptNumber?: string;
  storeId?: string;
  order?: string;
  source?: string;
  createdAtMin?: string;
  createdAtMax?: string;
  receiptDateMin?: string;
  receiptDateMax?: string;
  updatedAtMin?: string;
  updatedAtMax?: string;
}

export interface LoyverseSalesByItemQuery extends LoyverseReceiptQuery {
  includeCancelled?: boolean;
}

export interface LoyverseSalesByItemRow {
  itemId: string | null;
  variantId: string | null;
  itemName: string;
  variantName: string | null;
  sku: string;
  itemsSold: number;
  grossSales: number;
  itemsRefunded: number;
  refunds: number;
  discounts: number;
  netSales: number;
  costOfGoods: number;
  grossProfit: number;
  marginPercent: number;
  taxes: number;
}

export interface LoyverseSalesByItemTotals {
  itemsSold: number;
  grossSales: number;
  itemsRefunded: number;
  refunds: number;
  discounts: number;
